-- Arbeitsrecht Berufsbildung > Betriebswirtschaftliche Grundlagen > Finanzierungsarten > Kauf
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Wird beim Kauf von IT-Hardware das Eigentum sofort auf den Betrieb übertragen?', 2, '[{"text": "Ja", "correct": true, "because": "Beim Kauf geht das Eigentum direkt über"}, {"text": "Nein", "correct": false, "because": "Eigentumsübertragung ist beim Kauf üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen beim Kauf von Softwarelizenzen für einen IT-Betrieb laufende Kosten eingeplant werden?', 2, '[{"text": "Nein", "correct": true, "because": "Kauf bedeutet Einmalkosten, keine laufenden Kosten wie bei Leasing"}, {"text": "Ja", "correct": false, "because": "Kauf ist eine einmalige Zahlung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb durch den Kauf von Servern langfristig Kosten sparen?', 2, '[{"text": "Ja", "correct": true, "because": "Kauf vermeidet laufende Miet- oder Leasingkosten"}, {"text": "Nein", "correct": false, "because": "Langfristige Einsparungen sind möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist beim Kauf von IT-Ausrüstung eine hohe Anfangsinvestition erforderlich?', 2, '[{"text": "Ja", "correct": true, "because": "Kauf erfordert volle Zahlung upfront"}, {"text": "Nein", "correct": false, "because": "Hohe Anfangskosten sind typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein IT-Betrieb beim Kauf von Hardware Abschreibungen geltend machen?', 2, '[{"text": "Ja", "correct": true, "because": "Gekaufte Hardware wird als Anlagegut abgeschrieben"}, {"text": "Nein", "correct": false, "because": "Abschreibungen sind beim Kauf üblich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was ist ein wesentliches Merkmal der Finanzierungsart Kauf für einen IT-Betrieb?', 2, '[{"text": "Sofortige Eigentumsübertragung", "correct": true, "because": "Kauf bedeutet direkten Besitz"}, {"text": "Laufende Zahlungen", "correct": false, "because": "Das gilt für Leasing"}, {"text": "Keine Abschreibungen", "correct": false, "because": "Abschreibungen sind möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kosten entstehen einem IT-Betrieb typischerweise beim Kauf von Servern?', 3, '[{"text": "Einmalige Anschaffungskosten", "correct": true, "because": "Kauf erfordert volle Zahlung upfront"}, {"text": "Monatliche Leasingraten", "correct": false, "because": "Das gilt für Leasing"}, {"text": "Nur Wartungskosten", "correct": false, "because": "Anschaffungskosten sind primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Vorteil ergibt sich für einen IT-Betrieb durch den Kauf von Softwarelizenzen?', 3, '[{"text": "Langfristige Kostenersparnis", "correct": true, "because": "Keine laufenden Zahlungen wie bei Miete"}, {"text": "Geringere Anfangskosten", "correct": false, "because": "Kauf hat hohe Anfangskosten"}, {"text": "Keine Wartung erforderlich", "correct": false, "because": "Wartung bleibt notwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Finanzierungsquelle wird beim Kauf von IT-Ausrüstung häufig genutzt?', 2, '[{"text": "Eigenkapital", "correct": true, "because": "Kauf wird oft aus Eigenmitteln finanziert"}, {"text": "Fremdkapital", "correct": false, "because": "Möglich, aber nicht primär"}, {"text": "Leasingvertrag", "correct": false, "because": "Das ist eine andere Finanzierungsart"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nachteil des Kaufs von Hardware für einen IT-Betrieb?', 3, '[{"text": "Hohe Anfangsinvestition", "correct": true, "because": "Kauf erfordert sofortige Zahlung"}, {"text": "Keine Eigentumsübertragung", "correct": false, "because": "Eigentum wird übertragen"}, {"text": "Langfristige Abhängigkeit", "correct": false, "because": "Keine Abhängigkeit wie bei Leasing"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat die Finanzierungsart Kauf für einen IT-Betrieb?', 4, '[{"text": "Sofortige Eigentumsübertragung", "correct": true, "because": "Kauf bedeutet Besitz"}, {"text": "Hohe Anfangskosten", "correct": true, "because": "Volle Zahlung upfront"}, {"text": "Laufende Raten", "correct": false, "because": "Das gilt für Leasing"}, {"text": "Abschreibungsmöglichkeit", "correct": true, "because": "Anlagegut wird abgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet der Kauf von IT-Ausrüstung für einen IT-Betrieb?', 3, '[{"text": "Langfristige Kostenersparnis", "correct": true, "because": "Keine laufenden Zahlungen"}, {"text": "Volle Kontrolle über das Eigentum", "correct": true, "because": "Eigentum gehört dem Betrieb"}, {"text": "Geringe Anfangskosten", "correct": false, "because": "Anfangskosten sind hoch"}, {"text": "Steuerliche Vorteile durch Abschreibung", "correct": true, "because": "Abschreibungen sind möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat der Kauf von Hardware für einen IT-Betrieb?', 4, '[{"text": "Hohe Anfangsinvestition", "correct": true, "because": "Volle Zahlung erforderlich"}, {"text": "Schnelle technologische Veralterung", "correct": true, "because": "Hardware wird überholt"}, {"text": "Laufende Raten", "correct": false, "because": "Keine Raten beim Kauf"}, {"text": "Eingeschränkte Liquidität", "correct": true, "because": "Kapital wird gebunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kosten entstehen beim Kauf von Softwarelizenzen für einen IT-Betrieb?', 3, '[{"text": "Einmalige Anschaffungskosten", "correct": true, "because": "Kauf bedeutet Einmalzahlung"}, {"text": "Kosten für Wartung", "correct": true, "because": "Wartung kann zusätzlich anfallen"}, {"text": "Monatliche Mietkosten", "correct": false, "because": "Miete ist keine Kaufkosten"}, {"text": "Abschreibungen", "correct": true, "because": "Software kann abgeschrieben werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Was unterscheidet den Kauf von anderen Finanzierungsarten wie Leasing für einen IT-Betrieb?', 3, '[{"text": "Sofortiger Eigentumsübergang", "correct": true, "because": "Kauf überträgt Eigentum"}, {"text": "Keine laufenden Zahlungen", "correct": true, "because": "Einmalzahlung statt Raten"}, {"text": "Geringere Anfangskosten", "correct": false, "because": "Anfangskosten sind hoch"}, {"text": "Kapitalbindung", "correct": true, "because": "Kauf bindet Kapital"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Beim Kauf von Hardware wird das Eigentum sofort übertragen. b) Kauf erfordert laufende Zahlungen wie Leasing.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Eigentum ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kauf von Softwarelizenzen spart langfristig Kosten. b) Kauf hat hohe Anfangskosten.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "Langfristige Einsparung und hohe Anfangskosten"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Beim Kauf von Servern fallen Abschreibungen an. b) Kauf ist immer günstiger als Leasing.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abschreibungen ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Kauf bindet Kapital eines IT-Betriebs. b) Kauf erfordert keine Wartungskosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kapitalbindung ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Beim Kauf von IT-Ausrüstung entstehen hohe Anfangskosten. b) Kauf ist flexibler als Leasing.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Anfangskosten ja, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

